import{_ as i}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as e}from"./chunks/ON.DXVlsWbj.js";import{_ as s}from"./chunks/DIS.DdpTdGGD.js";import{_ as n}from"./chunks/EN.P9aPnFBv.js";import{_ as a}from"./chunks/OFF.BrU7kQE-.js";import{_ as o,o as r,c as p,a3 as l}from"./chunks/framework.g9mfNVRQ.js";const P=JSON.parse('{"title":"Inter applications","description":"","frontmatter":{"source_hash":"4a69400131","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"fr/use/interapp.md","filePath":"fr/use/interapp.md"}'),c={name:"fr/use/interapp.md"};function d(u,t,m,h,v,b){return r(),p("div",null,[...t[0]||(t[0]=[l('<div class="admonition xdrip"><p class="admonition-title"><img src="'+i+'" style="zoom:75%;"></p><p> Paramètres<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_open_in_app_grey600_48dp.png" style="width:5%;"> Paramètres inter applications</p></div><br><p>Paramètres inter applications propose deux façons de relier xDrip à d&#39;autres applications : la diffusion locale (interne à ce téléphone) et le service web (interne et externe).</p><h3 id="local-broadcast" tabindex="-1">Diffusion locale <a class="header-anchor" href="#local-broadcast" aria-label="Permalink to &quot;Diffusion locale {#local-broadcast}&quot;">​</a></h3><p>La diffusion locale fait envoyer à xDrip des messages internes qui peuvent être utilisés par d&#39;autres applications comme Nightwatch ou AAPS.</p><div class="admonition xdripitem"><p class="admonition-title">Diffusion locale <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Activer la diffusion locale de données pour que d&#39;autres applications (par exemple NightWatch) puisse écouter les nouvelles valeurs</p></div><p>Si vous utilisez des plugins d&#39;étalonnage ou un filtrage, vous pouvez choisir de diffuser les données brutes ou les données filtrées/étalonnées.</p><div class="admonition xdripitem"><p class="admonition-title">Envoyer la glycémie affichée <span class="symbol"><img src="'+s+'" style="zoom:75%;"></span></p><p> Utiliser le lissage du bruit et les plugins (si activés) pour les valeurs diffusées</p></div><p>Par sécurité, vous pouvez aussi bloquer la diffusion des données bruitées. Par défaut, seul le niveau de bruit extrême n&#39;est pas diffusé.</p><div class="admonition xdripitem"><p class="admonition-title">Blocage du bruit</p><p> Niveau à partir duquel les données bruitées ne devraient pas être diffusées car cela pourrait perturber les applis réceptrices</p></div><p>Les applications et téléphones récents devraient accepter la diffusion compatible. Ne la décochez pas.</p><div class="admonition xdripitem"><p class="admonition-title">Diffusion Compatible <span class="symbol"><img src="'+n+'" style="zoom:75%;"></span></p><p> Envoyer des broadcasts sans verrouiller le modèle de permission ancien</p></div><p>Vous pouvez indiquer le récepteur identifié si vous voulez que xDrip n&#39;envoie ses messages qu&#39;à une application précise. L&#39;usage le plus courant est lorsque xDrip est la source de données d&#39;<a href="https://androidaps.readthedocs.io/en/latest/Configuration/xdrip.html#identify-receiver" target="_blank" rel="noreferrer">AAPS</a>.</p><div class="admonition xdripitem"><p class="admonition-title">Identifier le récepteur</p><p> Envoyer uniquement au package nommé</p></div><h5 id="receiving-from-nsclient" tabindex="-1">Réception depuis NSClient. <a class="header-anchor" href="#receiving-from-nsclient" aria-label="Permalink to &quot;Réception depuis NSClient. {#receiving-from-nsclient}&quot;">​</a></h5><p>xDrip peut aussi recevoir des messages avec cette fonction : vous pouvez activer ou désactiver la réception des données et des traitements provenant d&#39;autres applications qui diffusent.</p><div class="admonition xdripitem"><p class="admonition-title">Accepter la Glycémie <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Traiter les données de glucose reçues de l&#39;application NSClient</p></div><div class="admonition xdripitem"><p class="admonition-title">Accepter les traitements <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Traiter les données de traitement reçues de NSClient</p></div><p>Vous pouvez activer ou désactiver (<strong>à désactiver pour AAPS !!!</strong>) le son joué après la mise à jour du profil xDrip.</p><div class="admonition xdripitem"><p class="admonition-title">Importer des sons <span class="symbol"><img src="'+s+'" style="zoom:75%;"></span></p><p> Jouer des sons lors de l&#39;importation de données significatives telles que des profils</p></div><p>Soyez prudent si vous acceptez les étalonnages d&#39;autres applications.</p><div class="admonition xdripitem"><p class="admonition-title">Accepter les Calibrations <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Traiter les calibrations reçus à partir d&#39;autres applications</p></div><h3 id="web-service" tabindex="-1">Service web <a class="header-anchor" href="#web-service" aria-label="Permalink to &quot;Service web {#web-service}&quot;">​</a></h3><p>Documentation d&#39;origine <a href="https://github.com/NightscoutFoundation/xDrip/blob/master/Documentation/technical/Local_Web_Services.md" target="_blank" rel="noreferrer">ici</a>.</p><div class="warning custom-block"><p class="custom-block-title">Attention</p><p>Si une autre application utilise le port 17580 (comme Diabox), désactivez cette fonction.<br> Notez que le service n&#39;est pas disponible en http sécurisé et que les applications <a href="./../smartwatch/smartwatch.html#fitbit">Fitbit</a> récentes peuvent refuser ses données.</p></div><p>Le service web ouvre un service web local sur votre appareil pour permettre à d&#39;autres appareils (montres) et applications d&#39;en recevoir des données.<br> Le serveur web répond aux requêtes à l&#39;adresse <code>127.0.0.1</code> sur le port <code>17580</code></p><div class="admonition xdripitem"><p class="admonition-title">Service Web xDrip <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Exploiter un serveur web local permettant d&#39;interagir avec Fitbit Ionic</p></div><p>Par défaut, le service web n&#39;est accessible qu&#39;à votre appareil ; vous pouvez l&#39;ouvrir pour que d&#39;autres appareils du réseau puissent y accéder. Assurez-vous d&#39;avoir vraiment besoin de cette fonction et d&#39;en comprendre les implications de sécurité. Assurez-vous qu&#39;un secret partagé est défini.</p><div class="admonition xdripitem"><p class="admonition-title">Service Web Ouvert <span class="symbol"><img src="'+s+'" style="zoom:75%;"></span></p><p> Accepter les connexions depuis n&#39;importe quel réseau au lieu de se limiter à l&#39;intérieur de cet appareil. Il y a des implications de sécurité pour activer ceci ! Le Secret partagé sera requis si défini.</p></div><div class="admonition xdripitem"><p class="admonition-title">Secret du Service Web xDrip</p><p> Secret partagé pour le service web ouvert (doit correspondre à votre secret Nightscout API)</p></div><h4 id="open-option" tabindex="-1">Option d&#39;ouverture <a class="header-anchor" href="#open-option" aria-label="Permalink to &quot;Option d&#39;ouverture {#open-option}&quot;">​</a></h4><p>Le service dispose d&#39;une option <code>Open Web Service</code> (Service Web Ouvert). Si elle est activée, les connexions peuvent passer par n&#39;importe quelle interface réseau au lieu d&#39;être limitées au réseau local de bouclage de l&#39;appareil. En général, activer cette option expose la connexion Wi-Fi / LAN / Bluetooth PAN de l&#39;appareil, mais elle pourrait aussi être exposée via le réseau mobile si l&#39;opérateur fournit des adresses IP publiques.</p><p>Soyez très prudent en activant cette option, car des fonctions puissantes sont accessibles, par exemple l&#39;interface tasker. Il est préférable de l&#39;utiliser avec l&#39;option d&#39;authentification décrite ci-dessous.</p><h4 id="authentication" tabindex="-1">Authentification <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentification {#authentication}&quot;">​</a></h4><p>Pour des raisons de sécurité (n&#39;importe qui sur le réseau peut accéder à ce service), vous devriez le protéger par un mot de passe ; si vous avez un site Nightscout, utilisez votre API_SECRET.</p><p>Si le <code>xDrip Web Service Secret</code> (Secret du Service Web xDrip) est défini à autre chose qu&#39;une chaîne vide (la valeur par défaut), les requêtes arrivant par les réseaux ouverts hors bouclage devront fournir un en-tête http <code>api-secret</code> contenant le hash SHA1 du même mot de passe secret, sinon leur connexion sera refusée. Les informations de refus sont enregistrées dans le Journal des événements et renvoyées dans la réponse http. Le code de résultat 403 (forbidden) est renvoyé lorsqu&#39;une connexion est refusée.</p><p>De plus, si un client fournit l&#39;en-tête <code>api-secret</code> alors que le secret xDrip n&#39;est pas défini, la requête sera refusée. Cette fonction permet aux appareils clients de s&#39;assurer qu&#39;ils se connectent à la bonne instance de xDrip (en utilisant des secrets différents). Cela peut être important, par exemple en boucle fermée.</p><p>L&#39;authentification n&#39;est pas requise sur l&#39;interface réseau locale de bouclage (127.0.0.1)</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>api-secret: 915858afa2278f25527f192038108346164b47f2</span></span></code></pre></div><p>Ci-dessus, l&#39;en-tête http pour le mot de passe <code>Abc</code></p><h4 id="nightscout-pebble-endpoint" tabindex="-1">Point d&#39;accès Nightscout Pebble <a class="header-anchor" href="#nightscout-pebble-endpoint" aria-label="Permalink to &quot;Point d&#39;accès Nightscout Pebble {#nightscout-pebble-endpoint}&quot;">​</a></h4><p><code>/pebble</code> émule la même URL de Nightscout : avec un cadran qui le prend en charge, vous pouvez saisir l&#39;adresse dans le cadran, par exemple définir le point d&#39;accès des données du cadran Pebble Nightscout à :</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:17580/pebble</span></span></code></pre></div><h4 id="sgvjson-endpoint" tabindex="-1">Point d&#39;accès sgv.json <a class="header-anchor" href="#sgvjson-endpoint" aria-label="Permalink to &quot;Point d&#39;accès sgv.json {#sgvjson-endpoint}&quot;">​</a></h4><p><code>/sgv.json</code> émule <code>/api/v1/entries/sgv.json?count=24</code> de Nightscout</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:17580/sgv.json</span></span></code></pre></div><p>Le premier enregistrement contient une indication sur les unités utilisées : <code>units_hint</code> vaut <code>mgdl</code> ou <code>mmol</code> pour indiquer la préférence de l&#39;utilisateur, mais les valeurs sont toujours envoyées en mgdl</p><p>Vous pouvez aussi accéder au point d&#39;accès des pas en ajoutant un paramètre de requête</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:17580/sgv.json?steps=1234</span></span></code></pre></div><p>Dans ce cas, cherchez le nombre <code>steps_result</code> dans le premier enregistrement de la réponse json : 200 indique un succès, toute autre valeur un échec de l&#39;enregistrement du nombre de pas. La valeur des pas doit être le compteur de pas cumulé actuel de l&#39;appareil.</p><p>Vous pouvez aussi accéder au point d&#39;accès de la fréquence cardiaque en ajoutant un paramètre de requête</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:17580/sgv.json?heart=123</span></span></code></pre></div><p>Dans ce cas, cherchez le nombre <code>heart_result</code> dans le premier enregistrement de la réponse json : 200 indique un succès, toute autre valeur un échec de l&#39;enregistrement de la fréquence cardiaque. La valeur doit être la fréquence cardiaque actuelle en bpm mesurée par l&#39;appareil.</p><p>Vous pouvez combiner les deux comme dans une chaîne de requête classique :</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:17580/sgv.json?steps=1234&amp;heart=123</span></span></code></pre></div><p>Une autre option, <code>brief_mode=Y</code>, permet d&#39;exclure certains champs de données des résultats pour réduire la taille de la réponse.</p><p>Une autre option, <code>no_empty=Y</code>, permet qu&#39;un jeu de données vide renvoie <code>&quot;&quot;</code> au lieu de <code>&quot;[]&quot;</code></p><p>Une autre option, <code>all_data=Y</code>, permet d&#39;obtenir en plus les données de la session de capteur précédente.</p><p>Une autre option, <code>sensor=Y</code>, permet d&#39;obtenir des données sur l&#39;âge du capteur</p><p>Une autre option, <code>collector=Y</code>, permet d&#39;obtenir les messages d&#39;alerte du collecteur. Rien n&#39;est renvoyé si le message est vide.</p><p>Vous pouvez aussi accéder au point d&#39;accès tasker en ajoutant un paramètre de requête</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:17580/sgv.json?tasker=osnooze</span></span></code></pre></div><p>cherchez <code>tasker_result</code> dans la première ligne de la réponse json pour savoir si l&#39;opération a réussi ou échoué.</p><p><code>OSNOOZE</code> est une mise en veille opportuniste que vous pouvez appeler même si aucune alerte n&#39;est en cours</p><p><code>SNOOZE</code> est la mise en veille tasker classique, qui envoie la mise en veille aux abonnés et utilise plus de CPU</p><h4 id="treatmentsjson-endpoint" tabindex="-1">Point d&#39;accès treatments.json <a class="header-anchor" href="#treatmentsjson-endpoint" aria-label="Permalink to &quot;Point d&#39;accès treatments.json {#treatmentsjson-endpoint}&quot;">​</a></h4><p><code>/treatments.json</code> émule <code>/api/v1/treatments.json?count=24</code> de Nightscout</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:17580/treatments.json</span></span></code></pre></div><h4 id="statusjson-endpoint" tabindex="-1">Point d&#39;accès status.json <a class="header-anchor" href="#statusjson-endpoint" aria-label="Permalink to &quot;Point d&#39;accès status.json {#statusjson-endpoint}&quot;">​</a></h4><p>Ce point d&#39;accès implémente un petit sous-ensemble des données que vous pourriez recevoir du status.json de Nightscout</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:17580/status.json</span></span></code></pre></div><p>Les résultats ressemblent à ceci :</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{&quot;thresholds&quot;:{&quot;bgHigh&quot;:9.4,&quot;bgLow&quot;:3.9}}</span></span></code></pre></div><p>Les seuils haut et bas définis dans l&#39;application, exprimés dans les unités locales.</p><h4 id="libre-2-endpoint" tabindex="-1">Point d&#39;accès Libre 2 <a class="header-anchor" href="#libre-2-endpoint" aria-label="Permalink to &quot;Point d&#39;accès Libre 2 {#libre-2-endpoint}&quot;">​</a></h4><p><code>/Libre2ConnectCode.json</code> renvoie le tampon de déverrouillage Bluetooth et l&#39;adresse Mac de l&#39;appareil.</p><p>Il est utilisé par <a href="./sync.html#whole-house">whole house</a>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:17580/Libre2ConnectCode.json</span></span></code></pre></div><h4 id="tasker-endpoint" tabindex="-1">Point d&#39;accès Tasker <a class="header-anchor" href="#tasker-endpoint" aria-label="Permalink to &quot;Point d&#39;accès Tasker {#tasker-endpoint}&quot;">​</a></h4><p>Le point d&#39;accès <code>/tasker</code> vous permet d&#39;envoyer des requêtes à l&#39;interface tasker via http. Ainsi, un cadran qui ne prend en charge que des points d&#39;accès web (par exemple FitBit) pourrait envoyer une demande de mise en veille comme ci-dessous :</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:17580/tasker/SNOOZE</span></span></code></pre></div><h4 id="steps-endpoint" tabindex="-1">Point d&#39;accès des pas <a class="header-anchor" href="#steps-endpoint" aria-label="Permalink to &quot;Point d&#39;accès des pas {#steps-endpoint}&quot;">​</a></h4><p><code>/steps</code> permet de définir les données actuelles du compteur de pas</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:17580/steps/set/1234</span></span></code></pre></div><p>Il doit s&#39;agir du compteur de pas cumulé actuel de l&#39;appareil qui mesure les pas, pas d&#39;un historique.</p><h4 id="heart-endpoint" tabindex="-1">Point d&#39;accès de la fréquence cardiaque <a class="header-anchor" href="#heart-endpoint" aria-label="Permalink to &quot;Point d&#39;accès de la fréquence cardiaque {#heart-endpoint}&quot;">​</a></h4><p><code>/heart</code> permet de définir la fréquence cardiaque actuelle en bpm</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:17580/heart/set/123/1</span></span></code></pre></div><p>Il doit s&#39;agir de la fréquence cardiaque actuelle en BPM sur l&#39;appareil de mesure, pas d&#39;un historique. Le premier paramètre est le BPM et le second la précision. Si vous n&#39;êtes pas sûr du paramètre de précision, mettez simplement 1.</p><br><h3 id="broadcast-service-api" tabindex="-1">API du service Broadcast <a class="header-anchor" href="#broadcast-service-api" aria-label="Permalink to &quot;API du service Broadcast {#broadcast-service-api}&quot;">​</a></h3><p>Ce service permet de diffuser les valeurs de xDrip sous forme d&#39;API et peut être utilisé par des applications externes comme <a href="https://bigdigital.home.blog/2022/06/16/watchdrip-a-new-application-for-xdrip-watch-integration" target="_blank" rel="noreferrer">WatchDrip+</a> (activez la fonction pour WatchDrip+).</p><div class="admonition xdripitem"><p class="admonition-title">API du service Broadcast <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Active la communication de xDrip avec des applications tiers en utilisant la nouvelle API</p></div><div class="admonition xdripitem"><p class="admonition-title">Inclure l&#39;InA dans l&#39;API <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Inclure l&#39;InA (insuline active) sur le point de terminaison de l&#39;API de service Web utilisé par certaines Smartwatch</p></div><div class="admonition xdripitem"><p class="admonition-title">Récupérer l&#39;InA depuis l&#39;application compagnon <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Récupérer l&#39;InA (insuline active) depuis l&#39;application compagnon s&#39;exécutant sur le même appareil, par exemple l&#39;app. Omnipod 5</p></div><br><h3 id="google-health-connect" tabindex="-1">Google Health connect <a class="header-anchor" href="#google-health-connect" aria-label="Permalink to &quot;Google Health connect {#google-health-connect}&quot;">​</a></h3><p>Vous pouvez partager des informations avec Google Health.</p><div class="admonition xdripitem"><p class="admonition-title">Google Health Connect</p><p> Envoyer et recevoir des données de Google Health Connect et Google Fit</p></div><p><a href="https://play.google.com/store/apps/details?id=com.google.android.apps.healthdata&amp;hl=en&amp;gl=US" target="_blank" rel="noreferrer">Health Connect</a> doit être installé sur votre appareil ; il est disponible à partir d&#39;Android 8.</p><div class="admonition xdripitem"><p class="admonition-title">Utiliser Health Connect <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Nécessite Android 8+ et l&#39;application Google compagnon ou Android 14+</p></div><p>Vous pouvez ensuite choisir d&#39;utiliser les données entrantes et d&#39;autoriser les données sortantes.</p><p>xDrip peut partager les pas, la fréquence cardiaque et la glycémie avec Google Health.</p><div class="admonition xdripitem"><p class="admonition-title">Recevoir les données de Health Connect <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p></div><div class="admonition xdripitem"><p class="admonition-title">Envoyer des données à Health Connect <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p></div><div class="admonition xdripitem"><p class="admonition-title">Gérer les permissions</p><p> Ouvrir les paramètres Health Connect pour gérer manuellement les autorisations</p></div><p>Sur certaines versions d&#39;Android (notamment 15 et 16), xDrip n&#39;est pas autorisé à ouvrir directement son écran d&#39;autorisations Health Connect. Il ouvre alors l&#39;application Health Connect : allez dans <em>Autorisations des applis</em> (App permissions) et sélectionnez xDrip pour les gérer. Si Health Connect ne peut pas du tout être ouvert, un message vous demande d&#39;ouvrir vous-même l&#39;application Health Connect et d&#39;y gérer les autorisations de xDrip.</p><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Dernière modification le 23/11/2026</em></a></p>',108)])])}const C=o(c,[["render",d]]);export{P as __pageData,C as default};
